def lr_success_rate(data, logistic_function, theta):
    success = 0
    for i in range(0, len(data)):
        if abs(logistic_function(data[i, 0], theta) - data[i, 1]) < 0.5:
            success = success + 1

    return 100.0 * success / len(data)
